import{_ as e,c as r,o as i,af as h}from"./chunks/framework.BKeRpnBD.js";const b=JSON.parse('{"title":"49、【革】 离下兑上","description":"温公易说 - 49、【革】 离下兑上","frontmatter":{"title":"49、【革】 离下兑上","description":"温公易说 - 49、【革】 离下兑上"},"headers":[],"relativePath":"zh/classics/wengong/050.md","filePath":"zh/classics/wengong/050.md"}'),n={name:"zh/classics/wengong/050.md"};function l(t,a,s,o,d,c){return i(),r("div",null,[...a[0]||(a[0]=[h('<h1 id="_49、【革】-离下兑上" tabindex="-1">49、【革】 离下兑上 <a class="header-anchor" href="#_49、【革】-离下兑上" aria-label="Permalink to “49、【革】 离下兑上”">​</a></h1><h3 id="彖曰-革-水火相息-二女同居-其志不相得-曰革。已日乃孚-革而信之。文明以说-大亨以正-革而当-其悔乃亡。" tabindex="-1">彖曰：革，水火相息，二女同居，其志不相得，曰革。已日乃孚，革而信之。文明以说，大亨以正，革而当，其悔乃亡。 <a class="header-anchor" href="#彖曰-革-水火相息-二女同居-其志不相得-曰革。已日乃孚-革而信之。文明以说-大亨以正-革而当-其悔乃亡。" aria-label="Permalink to “彖曰：革，水火相息，二女同居，其志不相得，曰革。已日乃孚，革而信之。文明以说，大亨以正，革而当，其悔乃亡。”">​</a></h3><p>天地革而四时成，汤武革命，顺乎天而应乎人。革之时，大矣哉。革之为道，不可易也。故元亨利贞，而后悔亡也。初则民心未孚，故巩用黄牛不可变也。二则得时之中，故已日革之，行有嘉也。</p><h3 id="象曰-泽中有火-革。君子以治历明时。" tabindex="-1">象曰：泽中有火，革。君子以治历明时。 <a class="header-anchor" href="#象曰-泽中有火-革。君子以治历明时。" aria-label="Permalink to “象曰：泽中有火，革。君子以治历明时。”">​</a></h3><h3 id="初九-巩用黄牛之革-象曰-巩用黄牛-不可以有为也。" tabindex="-1">初九：巩用黄牛之革 象曰：巩用黄牛，不可以有为也。 <a class="header-anchor" href="#初九-巩用黄牛之革-象曰-巩用黄牛-不可以有为也。" aria-label="Permalink to “初九：巩用黄牛之革 象曰：巩用黄牛，不可以有为也。”">​</a></h3><h3 id="六二-已日乃革之-征吉-无咎-象曰-已日革之-行有嘉也。" tabindex="-1">六二：已日乃革之，征吉，无咎 象曰：已日革之，行有嘉也。 <a class="header-anchor" href="#六二-已日乃革之-征吉-无咎-象曰-已日革之-行有嘉也。" aria-label="Permalink to “六二：已日乃革之，征吉，无咎 象曰：已日革之，行有嘉也。”">​</a></h3><h3 id="九三-征凶-贞厉-革言三就-有孚-象曰-革言三就-又何之矣。" tabindex="-1">九三：征凶，贞厉，革言三就，有孚 象曰：革言三就，又何之矣。 <a class="header-anchor" href="#九三-征凶-贞厉-革言三就-有孚-象曰-革言三就-又何之矣。" aria-label="Permalink to “九三：征凶，贞厉，革言三就，有孚 象曰：革言三就，又何之矣。”">​</a></h3><h3 id="九四-悔亡-有孚-改命-吉-象曰-改命之吉-信志也。" tabindex="-1">九四：悔亡，有孚，改命，吉 象曰：改命之吉，信志也。 <a class="header-anchor" href="#九四-悔亡-有孚-改命-吉-象曰-改命之吉-信志也。" aria-label="Permalink to “九四：悔亡，有孚，改命，吉 象曰：改命之吉，信志也。”">​</a></h3><h3 id="九五-大人虎变-未占-有孚-象曰-大人虎变-其文炳也。" tabindex="-1">九五：大人虎变，未占，有孚 象曰：大人虎变，其文炳也。 <a class="header-anchor" href="#九五-大人虎变-未占-有孚-象曰-大人虎变-其文炳也。" aria-label="Permalink to “九五：大人虎变，未占，有孚 象曰：大人虎变，其文炳也。”">​</a></h3><h3 id="上六-君子豹变-小人革面-征凶-居贞吉-象曰-君子豹变-其文蔚也。小人革面-顺以从君也。" tabindex="-1">上六：君子豹变，小人革面，征凶，居贞吉 象曰：君子豹变，其文蔚也。小人革面，顺以从君也。 <a class="header-anchor" href="#上六-君子豹变-小人革面-征凶-居贞吉-象曰-君子豹变-其文蔚也。小人革面-顺以从君也。" aria-label="Permalink to “上六：君子豹变，小人革面，征凶，居贞吉 象曰：君子豹变，其文蔚也。小人革面，顺以从君也。”">​</a></h3>',10)])])}const f=e(n,[["render",l]]);export{b as __pageData,f as default};
